// Recordings archive for /lineage. Data is generated by scripts/build-videos.mjs
// from the Eden Creators YouTube channel, where Eden Fractal, Optimism Fractal and
// the earlier fractally meetings were all published. Refresh with that script.
import data from '../data/fractal-videos.json';
import type { Era } from './timeline';

export interface FractalVideo {
  id: string;
  date: string;
  durationMin: number | null;
  title: string;
  series: string;
  episode: number | null;
  era: Era;
  url: string;
}

export interface VideoSeries {
  key: string;
  label: string;
  era: Era;
  count: number;
  first: string | null;
  last: string | null;
  videos: FractalVideo[];
}

const videos = data.videos as FractalVideo[];

export const VIDEO_COUNT: number = data.count;
export const VIDEOS_GENERATED: string = data.generated;

export const VIDEO_SERIES: VideoSeries[] = (data.series as Omit<VideoSeries, 'videos'>[]).map((s) => ({
  ...s,
  videos: videos.filter((v) => v.series === s.key),
}));

const BY_ID = new Map(videos.map((v) => [v.id, v]));

/** Look up one recording by YouTube id, for linking a milestone to its video. */
export function videoById(id: string): FractalVideo | undefined {
  return BY_ID.get(id);
}

export function formatDate(iso: string): string {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString('en-US', {
    year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC',
  });
}
